-- Populate wiki article: LEA-DSGN-013-01 Human Body Dimensions and Reach Ranges
-- Updates article content, sources, and EI prompt.

-- Ensure wiki_article_sources table exists (may not be in schema file yet)
CREATE TABLE IF NOT EXISTS public.wiki_article_sources (
  source_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id  UUID NOT NULL REFERENCES public.wiki_articles(article_id) ON DELETE CASCADE,
  label       TEXT NOT NULL,
  description TEXT,
  url         TEXT,
  source_type TEXT NOT NULL DEFAULT 'reference_standard',
  sort_order  SMALLINT NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

DO $$
DECLARE
  v_article_id uuid;
BEGIN

  UPDATE public.wiki_articles SET
    title            = 'Human Body Dimensions and Reach Ranges',
    subject_label    = 'LEA-DSGN-013 · Anthropometrics & Human Dimensions',
    difficulty_label = 'Foundational',
    lea_tests_you    = 'Apply percentile-based anthropometric data to size architectural elements, determine reach envelopes for standing, seated, and wheelchair users, verify furniture and fixture dimensions against human body measurements, and apply BP 344 accessible reach standards.',
    updated_note     = 'Updated March 21, 2026',
    status           = 'published',
    content          = E'Architecture is sized to the human body. Every dimension in the built environment — the height of a counter, the depth of a shelf, the width of a corridor — traces back to one source: the measurement of living, breathing people in all their variation.\n\nAnthropometrics is the science of measuring the human body. Architects use anthropometric data to make decisions that affect whether a space is usable, comfortable, and safe for the people who occupy it. The question is never "how tall is a person?" The question is always "how tall are the people who will use this space — the shortest and the tallest, the youngest and the oldest, the seated and the standing?"\n\nThe LEA tests whether you can translate body measurement data into specific design decisions. Given a counter height, can you determine whether a 5th percentile female can reach it comfortably? Given a shelf height, which users are excluded? Given a wheelchair user''s reach envelope, what counter height is required? This article provides the complete anthropometric foundation for those decisions.\n\n<KeyValues items={[{value: "1,740", label: "mm avg male height"}, {value: "1,622", label: "mm avg female height"}, {value: "435", label: "mm popliteal height"}, {value: "610", label: "mm max forward reach"}]} />\n\n---\n\n## The anthropometric foundation\n\n<WikiCalloutBox type="most-tested">\n**Design for the range, not the average.** Architectural elements must accommodate the 5th percentile female through the 95th percentile male. Designing for the 50th percentile (the "average person") excludes half the population by definition. The LEA tests whether you understand which percentile governs which design decision.\n</WikiCalloutBox>\n\nAnthropometric data is organized by percentile — a statistical ranking that describes the distribution of body measurements across a population.\n\n| Percentile | Meaning | Population it represents |\n|------------|---------|-------------------------|\n| 5th %ile | Small | 5% of the population is this size or smaller |\n| 50th %ile | Average | Half the population is smaller, half larger |\n| 95th %ile | Large | 95% of the population is this size or smaller |\n\nThe critical design insight: **different percentiles govern different design decisions.**\n\n- **Minimum clearances** (doorway widths, passage widths, knee clearance): use the **95th percentile** — the largest user must fit.\n- **Maximum reach heights** (overhead shelves, controls, switches): use the **5th percentile** — the smallest user must be able to reach.\n- **Comfortable working heights** (desk surfaces, counter heights): use the **50th percentile** as a reference, then adjust for the target user group.\n- **Seat heights**: use the **5th percentile popliteal height** — if the seat fits the smallest user''s leg length, larger users can still sit comfortably (feet flat on floor for all).\n\n<WikiCalloutBox type="lea-watch">\nThe LEA frequently presents questions where using the wrong percentile leads to an incorrect answer. A handrail sized for the 95th percentile male will be too high for the 5th percentile female. A shelf placed at the 50th percentile overhead reach excludes the shortest 50% of users. Always identify whether the design concern is clearance (use 95th) or reach (use 5th).\n</WikiCalloutBox>\n\n---\n\n## Standing body dimensions\n\n<BodyDimensionExplorer />\n\nThe following table lists the critical standing dimensions used in architectural design. All values are in millimetres from the floor, unshod (no shoes).\n\n| Dimension | 5th %ile Female | 50th %ile Female | 50th %ile Male | 95th %ile Male | Design application |\n|-----------|----------------|-----------------|---------------|---------------|--------------------|\n| Stature (height) | 1,508 | 1,622 | 1,740 | 1,867 | Door and passage heights; vertical clearances |\n| Eye height | 1,405 | 1,516 | 1,630 | 1,755 | Sight lines; signage mounting; counter service |\n| Shoulder height | 1,252 | 1,356 | 1,468 | 1,585 | Maximum comfortable shelf height; grab bar upper limit |\n| Elbow height | 945 | 1,023 | 1,105 | 1,190 | Standing work surface height (elbow minus 50–100 mm) |\n| Hip breadth | 310 | 370 | 351 | 401 | Minimum passage width; seat width |\n| Knuckle height | 665 | 720 | 775 | 840 | Handrail height reference |\n| Overhead reach | 1,800 | 1,940 | 2,060 | 2,220 | Maximum shelf height; emergency device placement |\n\n<Tip title="Standing Work Surface Height">\nThe standard counter height of 850–900 mm is derived from elbow height. A standing work surface should be **50–100 mm below elbow height** to allow arms to rest at a natural angle. For the 50th percentile female (elbow at 1,023 mm), the ideal work surface is 923–973 mm — hence the 900 mm standard. For precision work requiring close visual inspection, surfaces can be raised to elbow height.\n</Tip>\n\n---\n\n## Seated body dimensions\n\nSeated dimensions govern desk design, auditorium seating, vehicle interiors, and any space where users work or watch from a chair. All values are in millimetres.\n\n| Dimension | 5th %ile Female | 50th %ile Female | 50th %ile Male | 95th %ile Male | Design application |\n|-----------|----------------|-----------------|---------------|---------------|--------------------|\n| Seated height (erect) | 790 | 850 | 910 | 975 | Overhead clearance in theaters, transit; partition heights |\n| Seated eye height | 685 | 740 | 790 | 850 | Theater riser design; sightline calculations |\n| Seated shoulder height | 530 | 570 | 605 | 645 | Armrest height; partition visual privacy |\n| Elbow rest height | 185 | 215 | 235 | 270 | Armrest height above seat pan |\n| Thigh clearance | 130 | 148 | 160 | 185 | Minimum clearance under desk apron or table |\n| Popliteal height | 360 | 400 | 435 | 480 | Ideal seat height (feet flat on floor) |\n| Buttock-popliteal length | 430 | 470 | 490 | 535 | Seat depth (should not exceed this value) |\n| Knee height (seated) | 460 | 500 | 535 | 575 | Minimum clear height under desk or table |\n\n<WikiCalloutBox type="most-tested">\n**Popliteal height = seat height.** The popliteal height is the distance from the back of the knee to the floor. A chair seat set to the user''s popliteal height allows both feet to rest flat on the floor, distributing body weight properly across the thigh. Standard chair height of 430–450 mm is based on the 50th percentile male popliteal height of 435 mm. Adjustable chairs (380–520 mm range) accommodate the 5th percentile female (360 mm) through the 95th percentile male (480 mm).\n</WikiCalloutBox>\n\n**Theater riser design.** The seated eye height of the shortest anticipated user (5th percentile female: 685 mm) is the critical input for riser height calculations. To maintain unobstructed sight lines, each row must be raised so that the front-row occupant''s head does not block the rear-row occupant''s eye height. The isacoustic curve formula uses the 5th percentile seated eye height as the worst case.\n\n---\n\n## Reach envelopes\n\n<ReachEnvelopeDiagram />\n\nReach envelopes define the three-dimensional space a person can access without moving their base position. Architectural elements — shelves, controls, dispensers, switches, counters — must be placed within the reach envelope of their intended users.\n\n**Standing reach (50th percentile male)**\n\n| Reach type | Maximum | Comfortable | Design rule |\n|------------|---------|-------------|-------------|\n| Forward (unobstructed) | 610 mm | 460 mm | Depth of counters, workbenches |\n| Overhead (unobstructed) | 2,060 mm | 1,830 mm | Highest shelf; emergency pull stations |\n| Lowest comfortable | 380 mm AFF | — | Bottom shelf; lowest controls |\n| Side reach | 740 mm | 560 mm | Wall-mounted controls |\n\n**Seated reach (desk chair)**\n\n| Reach type | Maximum | Comfortable | Design rule |\n|------------|---------|-------------|-------------|\n| Forward | 560 mm | 410 mm | Desktop equipment placement |\n| Overhead | 1,370 mm | 1,220 mm | Overhead storage while seated |\n| Lowest | Seat level (~450 mm) | — | Below-desk storage reach |\n| Side reach | 680 mm | 510 mm | Lateral file reach from chair |\n\n**Wheelchair user reach (BP 344: 2024 Revised IRR)**\n\n| Reach type | Range | Notes |\n|------------|-------|-------|\n| Forward reach (unobstructed) | 380–1,220 mm AFF | Max 610 mm depth of obstruction |\n| Forward reach over obstruction | 380–1,065 mm AFF | Obstruction depth 255–510 mm |\n| Side reach (unobstructed) | 230–1,370 mm AFF | No obstruction |\n| Side reach with obstruction | 380–1,220 mm AFF | Obstruction depth ≤ 255 mm |\n| Accessible counter height | 730–860 mm | Section 5.1 |\n| Knee clearance (under counter) | 685 mm H × 800 mm D | For forward approach |\n| Clear floor space | 750 × 1,200 mm | At all accessible elements |\n\n<FormulaBlock label="Shelf Placement Rule" steps={[{variable: "H_max shelf", operator: "≤", operands: ["5th %ile overhead reach"], symbol: ""}, {variable: "", operator: "", operands: ["= 1,800 mm (5th %ile female standing overhead reach)"], comment: ""}, {variable: "H_min shelf", operator: "≥", operands: ["knee height (5th %ile)"], symbol: ""}, {variable: "", operator: "", operands: ["= 380 mm AFF (lowest accessible shelf per BP 344)"], comment: ""}, {variable: "Accessible range", operator: "=", operands: ["380 mm", "1,220 mm AFF (wheelchair forward reach)"], symbol: "to"}]} />\n\n---\n\n## Architectural applications\n\n<Tabs>\n<Tab label="Workstations" value="workstations">\n\nOffice workstations must accommodate the seated body. The critical dimensions govern desk height, monitor placement, chair adjustability, and knee clearance.\n\n| Element | Dimension | Basis |\n|---------|-----------|-------|\n| Desk surface height | 730–760 mm | Elbow height seated minus 50–100 mm |\n| Adjustable desk range | 680–1,200 mm | Seated to standing position |\n| Monitor distance from eyes | 460–710 mm | Arm''s length; visual acuity zone |\n| Monitor top edge | At or below eye level | Prevents neck extension |\n| Chair seat height | 430–450 mm fixed; 380–520 mm adjustable | Popliteal height range |\n| Knee clearance under desk | 680 mm minimum height | Thigh clearance + movement |\n| Desk depth (knee clearance) | 600 mm minimum | Thigh + forward lean |\n| Lumbar support height | 150–250 mm above seat | L3–L5 lumbar curve |\n| Armrest height above seat | 200–250 mm | Elbow rest height range |\n\n<WikiCalloutBox type="lea-watch">\nThe standard desk height of 730–760 mm is derived from the **seated elbow height** of the 50th percentile male (~235 mm above seat) plus the chair height (450 mm) minus 50 mm for wrist comfort = ~635 mm... but in practice the combined assembly settles to 730–760 mm. Memorize 730–760 mm as the LEA standard.\n</WikiCalloutBox>\n\n</Tab>\n<Tab label="Kitchens & Counters" value="kitchens">\n\nKitchen dimensions are derived from standing elbow height for the primary user population. Counter heights balance the needs of the 5th percentile female through the 95th percentile male.\n\n| Element | Dimension | Basis |\n|---------|-----------|-------|\n| Standard counter height | 850–900 mm | Elbow height minus 50–100 mm (standing) |\n| Accessible counter height | 730–860 mm | BP 344 §5.1 for wheelchair approach |\n| Counter depth (standard) | 600 mm | Forward reach comfortable depth |\n| Overhead cabinet: lowest shelf | 1,370–1,400 mm | 5th %ile female shoulder height |\n| Overhead cabinet: highest shelf | 1,800 mm max | 5th %ile female overhead reach |\n| Base cabinet height | 850–900 mm (with countertop) | Same as counter |\n| Knee clearance (accessible sink) | 685 mm H × 800 mm D | BP 344 wheelchair forward approach |\n| Island clearance (one cook) | 1,050 mm | Passage behind working cook |\n| Island clearance (two cooks) | 1,200 mm | Two people passing |\n\n<Tip title="Design Principle">\nThe 1,800 mm overhead shelf limit is not the structural maximum — it is the reach maximum for the 5th percentile female (overhead reach ~1,800 mm). Items above this height require a step stool for approximately 50% of female users. In accessible kitchens, overhead storage above 1,220 mm is inaccessible to wheelchair users.\n</Tip>\n\n</Tab>\n<Tab label="Stairs & Handrails" value="stairs">\n\nStair and handrail dimensions are directly derived from body measurements. The handrail height references the knuckle height — where the hand naturally falls when the arm hangs relaxed.\n\n| Element | Dimension | Basis |\n|---------|-----------|-------|\n| Handrail height (stairs) | 865–965 mm | Knuckle height range (5th F to 95th M) |\n| Handrail height (ramps, BP 344) | 865–965 mm | Same — measured vertically from ramp surface |\n| Riser height | 150–180 mm | Comfortable step-up; 175 mm is LEA standard |\n| Tread depth (going) | 250–300 mm | Foot length + overhang; 280 mm is LEA standard |\n| Stair width (residential) | 900 mm minimum | One person with clearance |\n| Stair width (public, egress) | 1,118 mm (44 inches) | Two-person egress (RA 9514) |\n| Landing depth | ≥ stair width | Full body stopping distance |\n| Headroom clearance | 2,100 mm minimum | 95th %ile male stature + safety margin |\n\n<FormulaBlock label="Handrail Height from Knuckle Height" steps={[{variable: "H_handrail", operator: "=", operands: ["knuckle height (standing)"], symbol: ""}, {variable: "Male 50th", operator: "=", operands: ["775 mm"], symbol: ""}, {variable: "Female 5th", operator: "=", operands: ["665 mm"], symbol: ""}, {variable: "LEA standard", operator: "=", operands: ["865 mm", "965 mm (accommodates range)"], symbol: "–"}]} />\n\n</Tab>\n<Tab label="BP 344 Accessible" value="bp344">\n\nBP 344 (2024 Revised IRR) sets specific reach ranges for wheelchair users. These override the general anthropometric guidelines for any accessible element.\n\n| Element | BP 344 Requirement | Reference |\n|---------|-------------------|----------|\n| Forward reach (unobstructed) | 380–1,220 mm AFF | §4.2 |\n| Side reach (unobstructed) | 230–1,370 mm AFF | §4.2 |\n| Accessible counter height | 730–860 mm | §5.1 |\n| Accessible counter length | 915 mm minimum | §5.1 |\n| Knee clearance height | 685 mm minimum | §5.1 |\n| Knee clearance depth | 800 mm minimum | §5.1 |\n| Toe clearance | 230 mm H × 150 mm D | §5.1 |\n| Clear floor space | 750 × 1,200 mm | §4.1 |\n| Turning radius | 1,500 mm diameter | §4.1 |\n| Accessible corridor width | 1,500 mm minimum | §3.1 |\n| Door clear width | 900 mm minimum | §6.1 |\n| Light switch height | 900–1,100 mm AFF | §7.1 |\n| Electrical outlet height | 450–1,200 mm AFF | §7.1 |\n\n<WikiCalloutBox type="lea-watch">\nThe 2024 Revised IRR of BP 344 updated accessible corridor widths from 1,200 mm to **1,500 mm**. Many review materials still show 1,200 mm — this is the pre-2024 value and is no longer correct. Always use 1,500 mm for accessible corridor minimum width on the LEA.\n</WikiCalloutBox>\n\n</Tab>\n</Tabs>\n\n---\n\n## Edward T. Hall''s proxemic zones\n\nAnthropometrics measures the body itself. Proxemics — the study of personal space distances — measures the invisible bubble of space people maintain around themselves in social situations. Architect Edward T. Hall identified four distance zones in his 1966 book *The Hidden Dimension*, each with direct implications for space planning.\n\n| Zone | Distance range | Description | Architectural implication |\n|------|---------------|-------------|---------------------------|\n| Intimate | 0–450 mm | Physical contact to close personal interaction | Private rooms; no circulation paths this close |\n| Personal | 450–1,200 mm | Arm''s length; comfortable conversation | Furniture arrangement; interview rooms; 1,200 mm corridor |\n| Social | 1,200–3,600 mm | Formal interaction; business distance | Office layouts; reception counters; meeting rooms |\n| Public | 3,600 mm+ | Formal address; performance space | Lecture halls; auditoriums; public plazas |\n\n<WikiCalloutBox type="most-tested">\nThe proxemic zones are tested in space planning questions. A reception counter designed for social-zone interaction should place the receptionist 1,200–3,600 mm from the visitor. A seminar room where the instructor addresses students informally is sized for the personal-to-social boundary (~1,200–2,400 mm depth). Open-plan offices use the social zone (1,200–3,600 mm) to create psychological separation between workstations.\n</WikiCalloutBox>\n\n**Design applications by zone:**\n\n- **Intimate zone (0–450 mm):** Only appropriate in private spaces. Hospital patient rooms, exam rooms, and therapy spaces must ensure intimate-zone interactions are shielded from others. Corridor widths of 900 mm force people to pass through each other''s personal zones — acceptable in residential, uncomfortable in extended encounters.\n\n- **Personal zone (450–1,200 mm):** The zone of normal conversation. Café seating, side-by-side workstations, and dining table arrangements operate in this zone. Standard dining clearance of 900 mm behind a seated diner places a passing person at the outer edge of the personal zone.\n\n- **Social zone (1,200–3,600 mm):** Business and formal social interaction. Counter heights of 900–1,100 mm, combined with the 1,200–1,800 mm social zone, create the psychological register of a service transaction. Conference rooms sized at 3,000–4,200 mm long keep participants within the social zone.\n\n- **Public zone (3,600 mm+):** One-to-many address. Lecture halls, auditoriums, and public gathering spaces are sized to the public zone. Stage-to-first-row distances in auditoriums typically start at 3,600–4,500 mm.\n\n---\n\n## Common mistakes\n\n<WikiMistakeList mistakes={[{number: 1, title: "Designing for the average instead of the range", wrongValue: "Counter height = 50th %ile elbow height", correctValue: "Design range accommodating 5th female through 95th male", explanation: "The 50th percentile is an average, not a design target. An element sized for the average excludes half the population. Always identify which percentile governs the design decision: 5th for reach maximums, 95th for clearance minimums."}, {number: 2, title: "Using male dimensions for unisex spaces", wrongValue: "Seat height = 435 mm (male 50th popliteal)", correctValue: "Adjustable 380–520 mm, or 430 mm fixed (compromise)", explanation: "The 5th percentile female popliteal height is 360 mm. A seat at 435 mm leaves her feet dangling. Unisex seating should be adjustable. Fixed seats in unisex spaces should target the 5th–50th percentile female range (360–400 mm) rather than the male average."}, {number: 3, title: "Confusing reach with clearance", wrongValue: "Highest shelf = 95th %ile overhead reach (2,220 mm)", correctValue: "Highest shelf ≤ 5th %ile overhead reach (1,800 mm)", explanation: "Reach dimensions use the smallest user (5th percentile) — the shelf must be reachable by everyone. Clearance dimensions use the largest user (95th percentile) — the opening must accommodate everyone. Applying the wrong percentile reverses the design intent."}, {number: 4, title: "Ignoring seated users in standing-height designs", wrongValue: "Counter height 900 mm — fine for everyone", correctValue: "900 mm counter excludes wheelchair users; requires 730–860 mm section", explanation: "BP 344 requires that any counter serving the public include an accessible section at 730–860 mm. A counter at 900 mm height is accessible to standing users but not to wheelchair users, who require knee clearance below and a lower surface to reach across."}, {number: 5, title: "Using outdated wheelchair dimensions (pre-2024 BP 344)", wrongValue: "Accessible corridor = 1,200 mm; reach range = 380–1,370 mm", correctValue: "Accessible corridor = 1,500 mm; forward reach max = 1,220 mm (unobstructed)", explanation: "The 2024 Revised IRR of BP 344 updated key dimensions. The accessible corridor minimum increased from 1,200 mm to 1,500 mm. The unobstructed forward reach maximum is 1,220 mm (not 1,370 mm — that applies to side reach). Review materials published before 2024 contain the old values."}]} />\n\n---\n\n## Dimension memory drill\n\n<BodyDimensionDrill />\n\n---\n\n## Check yourself\n\n<InlineQuiz question="A kitchen overhead cabinet has a lowest shelf at 1,500 mm AFF. Can a 5th percentile female reach it comfortably while standing?" options={[{text: "No — 5th percentile female comfortable overhead reach is approximately 1,400 mm, so 1,500 mm is beyond comfortable reach", is_correct: true}, {text: "Yes — 1,500 mm is well within standing reach for all users", is_correct: false}, {text: "Yes — the 5th percentile female overhead reach maximum is 1,800 mm", is_correct: false}, {text: "No — overhead shelves must not exceed 1,200 mm for any user", is_correct: false}]} rationale="The 5th percentile female overhead reach is approximately 1,800 mm maximum, but comfortable reach (without fully extending or standing on toes) is approximately 1,400 mm. A shelf at 1,500 mm requires arm extension beyond the comfortable zone for the smallest female users. The LEA distinguishes between maximum reach (absolute) and comfortable reach (sustained use). For kitchen shelves used regularly, comfortable reach governs." />\n\n<InlineQuiz question="What is the standard desk height and why?" options={[{text: "730–760 mm — derived from seated elbow height minus 50 mm for wrist comfort", is_correct: true}, {text: "850–900 mm — same as standard counter height", is_correct: false}, {text: "680–700 mm — based on knee clearance requirement", is_correct: false}, {text: "760–800 mm — based on the 95th percentile seated elbow height", is_correct: false}]} rationale="Standard desk height of 730–760 mm is derived from the seated elbow height of the 50th percentile male (~235 mm above the seat pan) plus the chair height (450 mm) minus approximately 50–100 mm for comfortable wrist position during keyboard/writing work. The 850–900 mm dimension applies to standing counters, not seated desks. The 680 mm dimension is the minimum knee clearance under the desk, not the surface height." />\n\n<InlineQuiz question="BP 344 requires an accessible forward reach range of:" options={[{text: "380–1,220 mm AFF (unobstructed forward reach)", is_correct: true}, {text: "450–1,370 mm AFF", is_correct: false}, {text: "300–1,500 mm AFF", is_correct: false}, {text: "380–1,065 mm AFF", is_correct: false}]} rationale="BP 344 §4.2 (2024 Revised IRR) sets the unobstructed forward reach range at 380–1,220 mm AFF. The 380–1,065 mm range applies when there is an obstruction of 255–510 mm depth. The 230–1,370 mm range applies to side reach (not forward reach). Controls, dispensers, and accessible elements must be placed within 380–1,220 mm AFF for unobstructed forward approach." />\n'
    WHERE slug = 'lea-dsgn-013-01'
    RETURNING article_id INTO v_article_id;

  IF v_article_id IS NULL THEN
    RAISE EXCEPTION 'No wiki_articles row found with slug = lea-dsgn-013-01';
  END IF;

  -- ── Sources ──────────────────────────────────────────────────
  DELETE FROM public.wiki_article_sources WHERE article_id = v_article_id;

  INSERT INTO public.wiki_article_sources (article_id, label, description, url, source_type, sort_order) VALUES
    (v_article_id, 'Panero & Zelnik', 'Human Dimension & Interior Space (1979) — the foundational anthropometric reference for architectural design; establishes percentile-based body measurement tables', NULL, 'reference_standard', 1),
    (v_article_id, 'Ernst Neufert', 'Architects'' Data, 4th Edition — body dimensions and their translation to furniture, fixture, and spatial design applications', NULL, 'reference_standard', 2),
    (v_article_id, 'Henry Dreyfuss', 'The Measure of Man and Woman (1993 revised edition) — humanscale anthropometric data with male/female percentile breakdowns', NULL, 'reference_standard', 3),
    (v_article_id, 'Edward T. Hall', 'The Hidden Dimension (1966) — defines the four proxemic distance zones (intimate, personal, social, public) and their architectural implications', NULL, 'reference_standard', 4),
    (v_article_id, 'BP 344 — 2024 Revised IRR', 'Accessible reach ranges (§4.2), counter heights (§5.1), clear floor space, knee clearance, and corridor widths for wheelchair users', NULL, 'implementing_rules', 5),
    (v_article_id, 'LEA Standard Dimensions', 'Licensure Exam standard body measurements and design values as applied in LEA design scenarios', NULL, 'prc_syllabus', 6);

  -- ── EI Prompt ─────────────────────────────────────────────────
  INSERT INTO public.wiki_ei_prompts (
    article_id,
    prompt_text,
    reveal_text,
    insert_after_heading,
    options,
    sort_order,
    is_active,
    status
  ) VALUES (
    v_article_id,
    'A pharmacy counter is 1,100 mm high. A wheelchair user needs to sign documents on this counter. Per BP 344, is this counter accessible?',
    'BP 344 §5.1 requires accessible counters to be 730–860 mm high. At 1,100 mm, this counter exceeds the maximum accessible height by 240 mm. The pharmacist must provide a lowered section at 860 mm maximum, or provide a clipboard at seated-accessible height. The accessible counter section must be at least 915 mm long, with knee clearance of 685 mm high × 800 mm deep below it to allow forward wheelchair approach. A counter at 1,100 mm is also above the 1,220 mm unobstructed forward reach maximum — but the reach concern is secondary to the approach height. The counter must be lowered.',
    'Reach envelopes',
    '[
      {"text": "No — 1,100 mm exceeds the 730–860 mm accessible counter range", "is_correct": true},
      {"text": "Yes — wheelchair users can reach up to 1,220 mm AFF", "is_correct": false},
      {"text": "Yes — counters are exempt from reach standards under BP 344", "is_correct": false},
      {"text": "No — the minimum counter height is 1,200 mm per BP 344", "is_correct": false}
    ]'::jsonb,
    0,
    true,
    'published'
  );

END $$;

